package ru.truetv.launcher;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.text.SpannableString;
import android.text.Spanned;
import android.text.style.ForegroundColorSpan;
import android.view.*;
import android.widget.*;

/** Stable icon area and reserved label area; focus never changes geometry. */
public final class Tile extends FrameLayout {
    public String pkg=""; public int slot=-1; public final ImageView image;private final TextView label;private final Glyph plus;private final View iconBox,frame;private boolean running;private final boolean menu;
    private DesktopGeometry.TileBox desktop;
    private final Paint dot=new Paint(Paint.ANTI_ALIAS_FLAG);
    public Tile(Context c,boolean menu){super(c);this.menu=menu;if(android.os.Build.VERSION.SDK_INT>=26)setDefaultFocusHighlightEnabled(false);setFocusable(true);setClickable(true);setId(View.generateViewId());setWillNotDraw(false);
        frame=new View(c);addView(frame);FrameLayout box=new FrameLayout(c);image=new ImageView(c);image.setScaleType(ImageView.ScaleType.FIT_CENTER);box.addView(image,new FrameLayout.LayoutParams(-1,-1));plus=new Glyph(c,"plus");box.addView(plus,new FrameLayout.LayoutParams(-1,-1));iconBox=box;addView(box);label=Ui.label(c,"",menu?12:13);label.setGravity(Gravity.CENTER);label.setMaxLines(menu?3:2);label.setMinLines(menu?3:2);label.setEllipsize(android.text.TextUtils.TruncateAt.END);if(!menu)label.setPadding(0,Ui.dp(c,4),0,0);addView(label);setOnFocusChangeListener((v,focus)->surface());surface();}
    public void bind(AppCatalog.Entry e,int slot){this.slot=slot;pkg=e==null?"":e.pkg;label.setText(e==null?"":e.label);plus.setVisibility(e==null?VISIBLE:GONE);image.setVisibility(e==null?GONE:VISIBLE);if(e!=null){if(e.disabled){String suffix=Ui.word(getContext()," (отключено)"," (disabled)");SpannableString t=new SpannableString(e.label+suffix);t.setSpan(new ForegroundColorSpan(Ui.DISABLED_RED),e.label.length(),t.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);label.setText(t);}AppCatalog.get(getContext()).image(e,image);}setContentDescription(e==null?Ui.word(getContext(),"Добавить приложение","Add app"):label.getText());running=false;invalidate();requestLayout();}
    private void surface(){SettingsStore s=new SettingsStore(getContext());int opacity=Choices.bound(s.number("opacity",10),0,100);boolean focus=hasFocus()||isSelected();int fill=focus?(!menu&&!Ui.light(getContext())?0x805e83aa:Ui.focusFill(getContext())):(menu?0:((opacity*255/100)<<24)|(Ui.light(getContext())?0x8b929c:0x2b303b));int stroke=focus?(!menu&&!Ui.light(getContext())?0xb3c3deea:Ui.focusBorder(getContext())):!menu&&s.flag("borders",true)?Ui.border(getContext()):0;android.graphics.drawable.GradientDrawable background=Ui.surface(getContext(),fill,stroke,menu?10:4);if(stroke!=0)background.setStroke(Ui.dp(getContext(),(hasFocus()||isSelected())?2:1),stroke);frame.setBackground(background);}
    public void setSelected(boolean value){super.setSelected(value);if(image!=null)surface();}
    public void running(boolean live){if(running!=live){running=live;invalidate();}}
    protected void onMeasure(int w,int h){super.onMeasure(w,h);int width=MeasureSpec.getSize(w),height=MeasureSpec.getSize(h);SettingsStore s=new SettingsStore(getContext());if(!menu){desktop=new DesktopGeometry.TileBox(width,height,Ui.dp(getContext(),8),s.flag("labels",true)?Ui.dp(getContext(),34):0,Ui.dp(getContext(),s.number("icon",0)));frame.measure(MeasureSpec.makeMeasureSpec(desktop.width,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(desktop.height,MeasureSpec.EXACTLY));iconBox.measure(MeasureSpec.makeMeasureSpec(desktop.iconSize,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(desktop.iconSize,MeasureSpec.EXACTLY));label.setVisibility(desktop.caption>0?VISIBLE:GONE);label.measure(MeasureSpec.makeMeasureSpec(desktop.iconSize,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(desktop.caption,MeasureSpec.EXACTLY));return;}boolean titles=menu||s.flag("labels",true);int caption=titles?Ui.dp(getContext(),menu?48:34):0;int pad=Ui.dp(getContext(),menu?4:8);int fixed=menu?s.number("menu_icon",64):s.number("icon",0);int limit=Math.max(1,Math.min(width,height)-Ui.dp(getContext(),4));int square=menu?width:fixed>0?Math.min(limit,Ui.dp(getContext(),fixed)+pad*2+caption):limit;int boxHeight=menu?height:square;
        frame.measure(MeasureSpec.makeMeasureSpec(square,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(boxHeight,MeasureSpec.EXACTLY));int available=Math.max(1,Math.min(square-pad*2,boxHeight-pad*2-caption));int side=fixed>0?Math.min(available,Ui.dp(getContext(),fixed)):available;iconBox.measure(MeasureSpec.makeMeasureSpec(side,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(side,MeasureSpec.EXACTLY));label.setVisibility(titles?VISIBLE:GONE);label.measure(MeasureSpec.makeMeasureSpec(Math.max(1,square-pad*2),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(caption,MeasureSpec.EXACTLY));}
    int iconLeft(){return iconBox.getLeft();}
    int iconRight(){return iconBox.getRight();}
    protected void onLayout(boolean changed,int l,int t,int r,int b){if(!menu){DesktopGeometry.TileBox d=desktop;frame.layout(d.left,d.top,d.left+d.width,d.top+d.height);iconBox.layout(d.iconLeft,d.iconTop,d.iconLeft+d.iconSize,d.iconTop+d.iconSize);label.layout(d.iconLeft,d.iconTop+d.iconSize,d.iconLeft+d.iconSize,d.iconTop+d.iconSize+d.caption);surface();return;}int square=frame.getMeasuredWidth(),height=frame.getMeasuredHeight(),left=(getWidth()-square)/2,top=(getHeight()-height)/2,pad=Ui.dp(getContext(),menu?4:8);frame.layout(left,top,left+square,top+height);int caption=label.getVisibility()==VISIBLE?label.getMeasuredHeight():0;int available=height-pad*2-caption;int side=iconBox.getMeasuredWidth(),x=(getWidth()-side)/2,y=menu?pad:top+pad+Math.max(0,(available-side)/2);iconBox.layout(x,y,x+side,y+side);label.layout(left+pad,top+height-pad-caption,left+square-pad,top+height-pad);surface();}
    protected void dispatchDraw(Canvas canvas){super.dispatchDraw(canvas);if(running&&iconBox.getWidth()>0){dot.setColor(Ui.GREEN);float radius=Ui.dp(getContext(),4);canvas.drawCircle(iconBox.getRight()-radius,iconBox.getTop()+radius,radius,dot);}}
}
